`timescale 1ns / 1ps
//=============================================================================
// Testbench: tb_poly_decompress
// Tests all 3 decompression modes (d=1, d=4, d=10) using KAT vectors
// from the HLS golden model (poly_data.h)
//
// Test flow:
//   1. Load compressed bytes into byte RAM
//   2. Start decompress with appropriate d_sel
//   3. Capture coefficient writes
//   4. Compare against expected golden values
//=============================================================================

module tb_poly_decompress();

    // =========================================================
    // 1. DUT Signals
    // =========================================================
    logic        clk;
    logic        rst_n;
    logic        start;
    logic [1:0]  d_sel;
    logic        done;

    logic [8:0]  byte_addr;
    logic [7:0]  byte_din;

    logic        coeff_we;
    logic [6:0]  coeff_addr;
    logic [15:0] coeff_a0;
    logic [15:0] coeff_a1;

    // =========================================================
    // 2. Input Byte RAM
    // =========================================================
    logic [7:0] input_byte_ram [0:383];

    always @(posedge clk) begin
        byte_din <= input_byte_ram[byte_addr];
    end

    // =========================================================
    // 3. Output Coefficient RAM
    // =========================================================
    logic [15:0] output_a0 [0:127];
    logic [15:0] output_a1 [0:127];

    always @(posedge clk) begin
        if (coeff_we) begin
            output_a0[coeff_addr] <= coeff_a0;
            output_a1[coeff_addr] <= coeff_a1;
        end
    end

    // =========================================================
    // 4. DUT Instantiation
    // =========================================================
    poly_decompress dut (
        .clk(clk),
        .rst_n(rst_n),
        .start(start),
        .d_sel(d_sel),
        .done(done),
        .byte_addr(byte_addr),
        .byte_din(byte_din),
        .coeff_we(coeff_we),
        .coeff_addr(coeff_addr),
        .coeff_a0(coeff_a0),
        .coeff_a1(coeff_a1)
    );

    // =========================================================
    // 5. Clock & Performance
    // =========================================================
    always #5 clk = ~clk;

    integer cycle_count;
    logic   is_running;

    always @(posedge clk) begin
        if (!rst_n) begin
            cycle_count <= 0;
            is_running  <= 0;
        end else begin
            if (start) begin
                cycle_count <= 0;
                is_running  <= 1;
            end else if (done)
                is_running <= 0;
            else if (is_running)
                cycle_count <= cycle_count + 1;
        end
    end

