            for (i = 0; i < 128; i++) begin
                if (output_a0[i] !== EXP_DECOMP_U[tc][2*i]) begin
                    if (errors < 5)
                        $display("   [ERROR] d=10 TC%0d coeff[%0d]: Got %0d, Exp %0d", tc, 2*i, output_a0[i], EXP_DECOMP_U[tc][2*i]);
                    errors++;
                end
                if (output_a1[i] !== EXP_DECOMP_U[tc][2*i+1]) begin
                    if (errors < 5)
                        $display("   [ERROR] d=10 TC%0d coeff[%0d]: Got %0d, Exp %0d", tc, 2*i+1, output_a1[i], EXP_DECOMP_U[tc][2*i+1]);
                    errors++;
                end
            end
            if (errors == 0) $display("   >> [PASS] Decompress d=10 TC%0d", tc);
            else begin
                $display("   >> [FAIL] Decompress d=10 TC%0d — %0d errors", tc, errors);
                total_errors += errors;
            end
        end

        // ===== Summary =====
        $display("=================================================");
        if (total_errors == 0)
            $display("   ALL DECOMPRESS TESTS PASSED! CONGRATS!        ");
        else
            $display("   DECOMPRESS TESTS FAILED — %0d total errors    ", total_errors);
        $display("=================================================");

        #50;
        $finish;
    end

endmodule
